            {
                ["Shared.BrandSubtitleShort"] = "Community · Respect · Equality",
                ["Shared.BrandSubtitleFull"] = "Community · Respect · Equality · Dedication · Order",
                ["Shared.OrganizationImageAlt"] = "C.R.E.D.O. organization image",

