                ["Shared.BackHome"] = "Back to Home",

                ["Home.PageTitle"] = "C.R.E.D.O. - Community. Respect. Excellence.",
                ["Home.Hero.Eyebrow"] = "Shared operations. Independent identities.",
                ["Home.Hero.Lead"] = "C.R.E.D.O. creates a shared operational home for individual players, established teams, and independent organizations. Existing communities retain their identity while their members collaborate across organizational boundaries in squads, departments, and shared projects.",
                ["Home.Hero.Connection"] = "This is where new connections are formed and where the strength to accomplish large-scale missions and shared objectives emerges.",
                ["Home.Hero.CollectiveStrength"] = "We combine skills, resources, and manpower to achieve goals together that would remain beyond the reach of individual groups.",
                ["Home.Hero.ExploreOrganization"] = "Explore Organization",
                ["Home.Hero.JoinOrganization"] = "Join the Organization",
                ["Home.Video.Title"] = "Watch Our Story",
                ["Home.Video.PlayAria"] = "Play video",
                ["Home.Organization.Title"] = "Organization & Culture",
                ["Home.Organization.Paragraph1"] = "C.R.E.D.O. is a Star Citizen organization built on the foundation of community, respect, excellence, dedication and order.",
                ["Home.Organization.Paragraph2"] = "We are more than a group of pilots. We are a team of citizens, explorers, builders and protectors who believe that structure, teamwork and trust create lasting success.",
                ["Home.Organization.Paragraph3"] = "Whether you are new to the verse or a seasoned veteran, you will find a place where your effort matters and your growth is supported.",
                ["Home.Values.Community.Title"] = "Community",
                ["Home.Values.Community.Text"] = "A welcoming and reliable group of citizens who value respect, loyalty and camaraderie.",
                ["Home.Values.Operations.Title"] = "Operations",
                ["Home.Values.Operations.Text"] = "From combat to cargo, exploration to support, we operate with purpose, structure and coordination.",
                ["Home.Values.Excellence.Title"] = "Excellence",
                ["Home.Values.Excellence.Text"] = "We strive to improve, prepare and act with discipline in everything we do as an organization.",

                ["Organization.PageTitle"] = "Organization - C.R.E.D.O.",
                ["Organization.Title"] = "Organization",
                ["Organization.Hero.LearnMore"] = "Learn more",
                ["Organization.StructureImageAlt"] = "C.R.E.D.O. operations room with crews coordinating around holographic planning displays.",
                ["Organization.Hero.Eyebrow"] = "Multi-org operations. One shared mission.",
                ["Organization.Hero.Motto"] = "Your Own Journey. United in Mission.",
                ["Organization.Hero.Lead"] = "C.R.E.D.O. is the operational home for Star Citizen players, crews, and organizations that want to think bigger together without giving up their own identity.",
                ["Organization.Hero.Intro"] = "We intentionally use the multi-organization principle: players and members of existing groups join C.R.E.D.O. directly, if needed as a secondary organization. This allows each group to keep its home, leadership, and culture while administration, roles, permissions, communication, and operation planning become easier within one shared system.",
                ["Organization.SharedHub.Title"] = "A shared hub instead of a classic mega-organization",
                ["Organization.SharedHub.Paragraph1"] = "Many groups in the Verse work well precisely because they are small, familiar, and coordinated. Their members know their own routines, culture, and the people behind the ships. At the same time, larger goals require more than a single crew can provide: logistics, security, supply, production, exploration, events, and strategic infrastructure only become reliable through coordinated cooperation.",
                ["Organization.SharedHub.Paragraph2"] = "C.R.E.D.O. does not replace existing communities. We expand their operational reach. If you already have a home organization, you keep it. If you are flying alone, you can find connection here. If you fly with a squad, you can take part in larger operations without losing your team identity.",
                ["Organization.SharedHub.Highlight"] = "You remain where you belong, join C.R.E.D.O., and still become part of something greater.",
                ["Organization.MultiOrg.Title"] = "Multi-org as a deliberate principle",
                ["Organization.MultiOrg.Paragraph1"] = "Star Citizen allows players to belong to multiple organizations. C.R.E.D.O. deliberately uses this principle. Joining C.R.E.D.O. does not automatically mean leaving or replacing an existing organization. It creates a shared organizational framework where everyone involved is visible, reachable, and ready for operations.",
                ["Organization.MultiOrg.Paragraph2"] = "This is especially important for smaller organizations. When their members also join C.R.E.D.O., roles, divisions, access, operation planning, and project participation can be managed more centrally. At the same time, C.R.E.D.O. represents the actual shared size externally: not just a loose agreement, but an active organization made up of players, squads, and partner groups.",
                ["Organization.MultiOrg.Label"] = "Primary or secondary organization",
                ["Organization.MultiOrg.Summary"] = "C.R.E.D.O. is built so players, squads, and smaller organizations can join directly while keeping their own identity, leadership, and internal culture.",
                ["Organization.Audience.Title"] = "Who C.R.E.D.O. is for",
                ["Organization.Audience.Individuals.Title"] = "Individual Players",
                ["Organization.Audience.Individuals.Text"] = "You join C.R.E.D.O. directly, find other players, take part in events, and develop your place within divisions, squads, and projects.",
                ["Organization.Audience.Squads.Title"] = "Squads",
                ["Organization.Audience.Squads.Text"] = "Established teams join C.R.E.D.O. and gain a framework for regularly contributing to larger operations.",
                ["Organization.Audience.Orgs.Title"] = "Existing Organizations",
                ["Organization.Audience.Orgs.Text"] = "Members of smaller organizations additionally join C.R.E.D.O. Their own organization remains their home, while C.R.E.D.O. becomes the shared operational and administrative space.",
                ["Organization.Collaboration.Title"] = "How collaboration works",
                ["Organization.Collaboration.Intro"] = "Community, squads, divisions, task forces, and projects connect different levels of collaboration.",
                ["Organization.Collaboration.Paragraph1"] = "C.R.E.D.O. connects several layers. The community is the shared space. Squads bring together players who regularly fly, fight, trade, salvage, mine, or produce together. Divisions collect interests and expertise. Task Forces assemble the exact players, ships, and capabilities needed for specific operations.",
                ["Organization.Collaboration.Paragraph2"] = "This keeps the structure flexible. Not everyone has to do everything all the time. Not every organization has to participate in every project. But when a larger objective appears, there is a framework for bringing resources, crews, and specialists together with purpose.",
                ["Organization.Elements.Squads.Title"] = "Squads",
                ["Organization.Elements.Squads.Text"] = "Small, coordinated teams: fixed ship crews, boarding teams, escorts, salvage groups, mining teams, racing crews, or logistics teams.",
                ["Organization.Elements.Divisions.Title"] = "Divisions",
                ["Organization.Elements.Divisions.Text"] = "Gameplay-focused departments, such as Security, Industry, Mining, Salvage, Logistics, Trade, Exploration, Science & Engineering, or Medical.",
                ["Organization.Elements.TaskForces.Title"] = "Task Forces",
                ["Organization.Elements.TaskForces.Text"] = "Temporary operation groups for specific goals such as convoys, base building, area scouting, defense, events, or multi-week campaigns.",
                ["Organization.Elements.Projects.Title"] = "Campaigns & Projects",
                ["Organization.Elements.Projects.Text"] = "Multi-stage operations and long-term initiatives with visible contributions, transparent planning, and clear rules for resources, returns, and infrastructure.",
                ["Organization.Projects.Title"] = "Shared projects with lasting value",
                ["Organization.Projects.Paragraph1"] = "The value of C.R.E.D.O. becomes visible where individual groups reach their limits: building a base, operating shared infrastructure, creating production chains, establishing trade routes, maintaining strategic storage, coordinating mining, organizing escorts, building rescue and support structures, or running large community events.",
                ["Organization.Projects.Paragraph2"] = "Transparency matters. Anyone who contributes resources, time, or expertise should understand what their contribution is used for, who makes decisions, and what rights, returns, or usage rules result from it. C.R.E.D.O. should create trust, not anonymous stockpiles.",
                ["Organization.Promise.Title"] = "The promise to smaller organizations",
                ["Organization.Promise.Paragraph1"] = "C.R.E.D.O. does not mean your organization disappears. We do not want to poach members, take over internal decisions, or replace established structures. Your leadership, rules, projects, and identity remain yours.",
                ["Organization.Promise.Paragraph2"] = "Joining C.R.E.D.O. is therefore not a break from your home, but a shared access point. Your members can use C.R.E.D.O. as a secondary organization so that administration, communication, operational readiness, and visible shared size become easier to manage.",
                ["Organization.Promise.Paragraph3"] = "This allows you to think bigger, participate in larger operations, find specialists, request support, use infrastructure, and achieve goals with other groups that would be difficult to reach alone.",
                ["Organization.Values.Title"] = "Our values",
                ["Organization.Values.Intro"] = "C.R.E.D.O. stands for Community. Respect. Equality. Dedication. Order. These values describe how we want to treat each other and how we want to lead shared efforts.",
                ["Organization.Values.Community.Title"] = "Community",
                ["Organization.Values.Community.Text"] = "Cooperation matters more than ego. We create a place where players find connection and groups can work together.",
                ["Organization.Values.Respect.Title"] = "Respect",
                ["Organization.Values.Respect.Text"] = "Every group and every player is taken seriously - regardless of size, experience, playstyle, or previous affiliation.",
                ["Organization.Values.Equality.Title"] = "Equality",
                ["Organization.Values.Equality.Text"] = "Origin, organization, or ownership do not decide whether someone belongs. Contributions matter where they create impact.",
                ["Organization.Values.Dedication.Title"] = "Dedication",
                ["Organization.Values.Dedication.Text"] = "We do not only announce goals. We work on them together, develop projects further, and take responsibility.",
                ["Organization.Values.Order.Title"] = "Order",
                ["Organization.Values.Order.Text"] = "Large efforts need structure, clear communication, and reliable processes without losing the fun of the game.",
                ["Organization.Joining.Title"] = "Become part of the hub",
                ["Organization.Joining.Text1"] = "Whether you fly alone, have a fixed crew, or represent your own organization: C.R.E.D.O. gives you a place where you can contribute without giving up your identity.",
                ["Organization.Joining.Text2"] = "Join C.R.E.D.O., bring your strengths, and keep your home. As a primary or secondary organization: C.R.E.D.O. connects players, crews, and organizations for what only becomes possible together in the Verse.",
                ["Organization.Joining.JoinUs"] = "Join C.R.E.D.O.",
                ["Organization.Joining.Contact"] = "Contact",

