                ["Shared.BrandSubtitleShort"] = "Gemeinschaft · Respekt · Gleichwertigkeit",
                ["Shared.BrandSubtitleFull"] = "Gemeinschaft · Respekt · Gleichwertigkeit · Hingabe · Ordnung",
