                ["Shared.BackHome"] = "Zur Startseite",

                ["Home.PageTitle"] = "C.R.E.D.O. - Gemeinschaft. Respekt. Exzellenz.",
                ["Home.Hero.Eyebrow"] = "Gemeinsame Operationen. Eigene Identitäten.",
                ["Home.Hero.Lead"] = "C.R.E.D.O. schafft eine gemeinsame operative Heimat für Spieler, eingespielte Teams und eigenständige Organisationen. Bestehende Gemeinschaften behalten ihre Identität, während ihre Mitglieder organisationsübergreifend in Squads, Abteilungen und gemeinsamen Projekten zusammenarbeiten.",
                ["Home.Hero.Connection"] = "Hier entstehen neue Verbindungen und die Stärke, große Missionen und gemeinsame Vorhaben zu verwirklichen.",
                ["Home.Hero.CollectiveStrength"] = "Wir bündeln Fähigkeiten, Ressourcen und Manpower, um gemeinsam Ziele zu erreichen, die für einzelne Gruppen unerreichbar bleiben.",
                ["Home.Hero.ExploreOrganization"] = "Organisation entdecken",
                ["Home.Hero.JoinOrganization"] = "Organisation beitreten",
                ["Home.Video.Title"] = "Unsere Geschichte ansehen",
                ["Home.Video.PlayAria"] = "Video abspielen",
                ["Home.Organization.Title"] = "Organisation & Kultur",
                ["Home.Organization.Paragraph1"] = "C.R.E.D.O. ist eine Star-Citizen-Organisation auf dem Fundament von Gemeinschaft, Respekt, Exzellenz, Hingabe und Ordnung.",
                ["Home.Organization.Paragraph2"] = "Wir sind mehr als eine Gruppe von Piloten. Wir sind ein Team aus Citizens, Entdeckern, Aufbauern und Beschützern, die daran glauben, dass Struktur, Teamwork und Vertrauen nachhaltigen Erfolg schaffen.",
                ["Home.Organization.Paragraph3"] = "Ob du neu im Verse bist oder ein erfahrener Veteran: Bei uns findest du einen Platz, an dem dein Einsatz zählt und deine Entwicklung unterstützt wird.",
                ["Home.Values.Community.Title"] = "Gemeinschaft",
                ["Home.Values.Community.Text"] = "Eine einladende und verlässliche Gruppe von Citizens, die Respekt, Loyalität und Zusammenhalt schätzt.",
                ["Home.Values.Operations.Title"] = "Operationen",
                ["Home.Values.Operations.Text"] = "Von Kampf bis Cargo, von Erkundung bis Support: Wir handeln mit Ziel, Struktur und Koordination.",
                ["Home.Values.Excellence.Title"] = "Exzellenz",
                ["Home.Values.Excellence.Text"] = "Wir wollen uns verbessern, vorbereiten und in allem, was wir als Organisation tun, diszipliniert handeln.",

                ["Organization.PageTitle"] = "Organisation - C.R.E.D.O.",
                ["Organization.Title"] = "Organisation",
                ["Organization.Hero.LearnMore"] = "Mehr erfahren",
                ["Organization.StructureImageAlt"] = "C.R.E.D.O.-Operationsraum mit Crews an holografischen Planungstischen.",
                ["Organization.Hero.Eyebrow"] = "Multi-Orga-Operationen. Eine gemeinsame Mission.",
                ["Organization.Hero.Motto"] = "Eigene Wege. Gemeinsamer Kurs.",
                ["Organization.Hero.Lead"] = "C.R.E.D.O. ist die operative Heimat für Star-Citizen-Spieler, Crews und Organisationen, die gemeinsam größer denken wollen, ohne ihre eigene Identität aufzugeben.",
                ["Organization.Hero.Intro"] = "Wir nutzen das Multi-Orga-Prinzip bewusst: Spieler und Mitglieder bestehender Gruppen treten C.R.E.D.O. direkt bei, bei Bedarf als Zweitorganisation. So bleiben Heimat, Führung und Kultur erhalten, während Verwaltung, Rollen, Rechte, Kommunikation und Einsatzplanung in einem gemeinsamen System einfacher werden.",
                ["Organization.SharedHub.Title"] = "Ein gemeinsamer Hub statt klassischer Großorganisation",
                ["Organization.SharedHub.Paragraph1"] = "Viele Gruppen im Verse funktionieren gerade deshalb gut, weil sie klein, vertraut und eingespielt sind. Man kennt die eigenen Abläufe, die Kultur und die Menschen hinter den Schiffen. Gleichzeitig brauchen größere Vorhaben mehr als eine einzelne Crew leisten kann: Logistik, Schutz, Versorgung, Produktion, Erkundung, Events und strategische Infrastruktur entstehen erst durch verlässliche Zusammenarbeit.",
                ["Organization.SharedHub.Paragraph2"] = "C.R.E.D.O. ersetzt diese gewachsenen Gemeinschaften nicht. Wir erweitern ihren Aktionsradius. Wer bereits eine Heimatorganisation hat, behält sie. Wer allein unterwegs ist, findet bei uns Anschluss. Wer mit einem Squad fliegt, kann Teil größerer Operationen werden, ohne die eigene Teamidentität zu verlieren.",
                ["Organization.SharedHub.Highlight"] = "Du bleibst, wo du hingehörst, trittst C.R.E.D.O. bei und kannst trotzdem Teil von etwas Größerem werden.",
                ["Organization.MultiOrg.Title"] = "Multi-Orga als bewusstes Prinzip",
                ["Organization.MultiOrg.Paragraph1"] = "Star Citizen ermöglicht es Spielern, mehreren Organisationen anzugehören. C.R.E.D.O. nutzt genau dieses Prinzip. Der Beitritt zu C.R.E.D.O. bedeutet nicht automatisch, dass eine bestehende Organisation aufgegeben oder ersetzt wird. Er schafft einen gemeinsamen organisatorischen Rahmen, in dem alle Beteiligten sichtbar, erreichbar und einsatzfähig sind.",
                ["Organization.MultiOrg.Paragraph2"] = "Gerade für kleinere Organisationen ist das wichtig. Wenn ihre Mitglieder C.R.E.D.O. zusätzlich beitreten, können Rollen, Divisionen, Zugänge, Einsatzplanung und Projektbeteiligungen zentraler verwaltet werden. Gleichzeitig repräsentiert C.R.E.D.O. nach außen die tatsächliche gemeinsame Größe: nicht nur eine lose Absprache, sondern eine aktive Organisation aus Spielern, Squads und Partnergruppen.",
                ["Organization.MultiOrg.Label"] = "Haupt- oder Zweitorganisation",
                ["Organization.MultiOrg.Summary"] = "C.R.E.D.O. ist darauf ausgelegt, dass Spieler, Squads und kleinere Organisationen direkt beitreten können, ohne ihre eigene Identität, Führung oder interne Kultur aufzugeben.",
                ["Organization.Audience.Title"] = "Für wen C.R.E.D.O. gedacht ist",
                ["Organization.Audience.Individuals.Title"] = "Einzelspieler",
                ["Organization.Audience.Individuals.Text"] = "Du trittst C.R.E.D.O. direkt bei, findest Mitspieler, nimmst an Events teil und kannst dich in Divisionen, Squads und Projekten entwickeln.",
                ["Organization.Audience.Squads.Title"] = "Squads",
                ["Organization.Audience.Squads.Text"] = "Eingespielte Teams treten C.R.E.D.O. bei und erhalten einen Rahmen, um regelmäßig an größeren Einsätzen mitzuwirken.",
                ["Organization.Audience.Orgs.Title"] = "Bestehende Organisationen",
                ["Organization.Audience.Orgs.Text"] = "Mitglieder kleinerer Orgas treten C.R.E.D.O. zusätzlich bei. Die eigene Organisation bleibt Heimat, C.R.E.D.O. wird der gemeinsame Einsatz- und Verwaltungsraum.",
                ["Organization.Collaboration.Title"] = "Wie Zusammenarbeit bei uns funktioniert",
                ["Organization.Collaboration.Intro"] = "Community, Squads, Divisionen, Task Forces und Projekte verbinden unterschiedliche Ebenen der Zusammenarbeit.",
                ["Organization.Collaboration.Paragraph1"] = "C.R.E.D.O. verbindet mehrere Ebenen miteinander. Die Community ist der gemeinsame Raum. Squads bringen Spieler zusammen, die regelmäßig miteinander fliegen, kämpfen, handeln, bergen oder produzieren. Divisionen bündeln Interessen und Fachwissen. Task Forces stellen für konkrete Einsätze genau die Spieler, Schiffe und Fähigkeiten zusammen, die gebraucht werden.",
                ["Organization.Collaboration.Paragraph2"] = "Dadurch bleibt die Struktur flexibel. Nicht jeder muss immer alles machen. Nicht jede Organisation muss sich an jedem Projekt beteiligen. Wenn aber ein großes Ziel ansteht, gibt es einen Rahmen, um Ressourcen, Crews und Spezialisten gezielt zusammenzubringen.",
                ["Organization.Elements.Squads.Title"] = "Squads",
                ["Organization.Elements.Squads.Text"] = "Kleine, eingespielte Teams: feste Schiffcrews, Boarding-Teams, Eskorten, Salvage-Gruppen, Mining-Teams, Racing-Crews oder Logistikteams.",
                ["Organization.Elements.Divisions.Title"] = "Divisionen",
                ["Organization.Elements.Divisions.Text"] = "Fachbereiche nach Gameplay und Interesse, zum Beispiel Security, Industry, Mining, Salvage, Logistics, Trade, Exploration, Science & Engineering oder Medical.",
                ["Organization.Elements.TaskForces.Title"] = "Task Forces",
                ["Organization.Elements.TaskForces.Text"] = "Temporäre Einsatzgruppen für konkrete Ziele wie Konvois, Basisbau, Gebietserkundung, Verteidigung, Events oder mehrwöchige Kampagnen.",
                ["Organization.Elements.Projects.Title"] = "Kampagnen und Projekte",
                ["Organization.Elements.Projects.Text"] = "Mehrstufige Operationen und langfristige Vorhaben mit sichtbaren Beiträgen, transparenter Planung und nachvollziehbarer Nutzung von Ressourcen, Erträgen und Infrastruktur.",
                ["Organization.Projects.Title"] = "Gemeinsame Projekte mit bleibendem Wert",
                ["Organization.Projects.Paragraph1"] = "Der Mehrwert von C.R.E.D.O. zeigt sich dort, wo einzelne Gruppen allein an Grenzen stoßen: beim Aufbau einer Basis, beim Betrieb gemeinsamer Infrastruktur, bei Produktionsketten, Handelsrouten, strategischen Lagern, koordiniertem Mining, organisierter Eskorte, Rettungs- und Supportstrukturen oder großen Community-Events.",
                ["Organization.Projects.Paragraph2"] = "Wichtig ist Transparenz. Wer Ressourcen, Zeit oder Know-how beiträgt, soll verstehen, wofür dieser Beitrag eingesetzt wird, wer Entscheidungen trifft und welche Rechte, Erträge oder Nutzungsregeln daraus entstehen. C.R.E.D.O. soll Vertrauen schaffen, nicht anonyme Lager füllen.",
                ["Organization.Promise.Title"] = "Das Versprechen an kleine Organisationen",
                ["Organization.Promise.Paragraph1"] = "C.R.E.D.O. bedeutet nicht, dass eure Organisation verschwindet. Wir wollen keine Mitglieder abwerben, keine internen Entscheidungen übernehmen und keine gewachsene Struktur ersetzen. Eure Führung, eure Regeln, eure Projekte und eure Identität bleiben eure Sache.",
                ["Organization.Promise.Paragraph2"] = "Der Beitritt zu C.R.E.D.O. ist deshalb kein Bruch mit eurer Heimat, sondern ein gemeinsamer Zugangspunkt. Eure Mitglieder können C.R.E.D.O. als Zweitorga nutzen, damit Verwaltung, Kommunikation und Einsatzfähigkeit einfacher werden und die gemeinsame Größe sichtbar wird.",
                ["Organization.Promise.Paragraph3"] = "So könnt ihr größer denken, an großen Operationen teilnehmen, Spezialisten finden, Unterstützung anfordern, Infrastruktur nutzen und gemeinsam mit anderen Gruppen Ziele erreichen, die allein nur schwer möglich wären.",
                ["Organization.Values.Title"] = "Unsere Werte",
                ["Organization.Values.Intro"] = "C.R.E.D.O. steht für Community. Respect. Equality. Dedication. Order. Diese Werte beschreiben, wie wir miteinander umgehen und wie wir gemeinsame Vorhaben führen wollen.",
                ["Organization.Values.Community.Title"] = "Community",
                ["Organization.Values.Community.Text"] = "Zusammenarbeit ist wichtiger als Ego. Wir schaffen einen Ort, an dem Spieler Anschluss finden und Gruppen miteinander wirken können.",
                ["Organization.Values.Respect.Title"] = "Respect",
                ["Organization.Values.Respect.Text"] = "Jede Gruppe und jeder Spieler wird ernst genommen - unabhängig von Größe, Erfahrung, Spielstil oder bisheriger Zugehörigkeit.",
                ["Organization.Values.Equality.Title"] = "Equality",
                ["Organization.Values.Equality.Text"] = "Herkunft, Organisation oder Besitz entscheiden nicht darüber, ob jemand dazugehört. Beiträge zählen dort, wo sie Wirkung entfalten.",
                ["Organization.Values.Dedication.Title"] = "Dedication",
